const b = $input.first().json.body || {};
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const rows = (b.champs || []).map(c => `<tr><td style="padding:6px 12px;font-weight:600;vertical-align:top">${esc(c.label)}</td><td style="padding:6px 12px">${esc(c.value).replace(/\n/g,'<br>')}</td></tr>`).join('');
const html = `<p>Nouveau message depuis le site (${esc(b.formulaire)}).</p><table style="border-collapse:collapse">${rows}</table><p style="color:#888;font-size:12px">Page : ${esc(b.page)}<br>Reçu le ${esc(b.date)}</p>`;
const email = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(b.email || '') ? b.email : '';
return [{ json: { subject: `[Site] ${b.formulaire || 'Message'}`, html, replyTo: email } }];
